   852    std::vector<ComplexSelectorObj>
   853      CompoundSelector::resolve_parent_refs(SelectorStack pstack, Backtraces& traces, bool implicit_parent)
   854    {
   855
   856      auto parent = pstack.back();
   857      std::vector<ComplexSelectorObj> rv;
   858
   859      for (SimpleSelectorObj simple : elements()) {
   860        if (Pseudo_Selector * pseudo = Cast<Pseudo_Selector>(simple)) {
   861          if (SelectorList* sel = Cast<SelectorList>(pseudo->selector())) {
   862            if (parent) {
   863              pseudo->selector(sel->resolve_parent_refs(
   864                pstack, traces, implicit_parent));
   865            }
   866          }
   867        }
   868      }
   869
   870      // Mix with parents from stack
   871      if (hasRealParent()) {
   872
   873        if (parent.isNull()) {
   874          return { wrapInComplex() };
   875        }
   876        else {
   877          for (auto complex : parent->elements()) {
   878            // The parent complex selector has a compound selector
   879            if (CompoundSelectorObj tail = Cast<CompoundSelector>(complex->last())) {
   880              // Create a copy to alter it
   881              complex = SASS_MEMORY_COPY(complex);
   882              tail = SASS_MEMORY_COPY(tail);
   883
   884              // Check if we can merge front with back
   885              if (length() > 0 && tail->length() > 0) {
   886                SimpleSelectorObj back = tail->last();
   887                SimpleSelectorObj front = first();
   888                auto simple_back = Cast<SimpleSelector>(back);
   889                auto simple_front = Cast<Type_Selector>(front);
   890                if (simple_front && simple_back) {
   891                  simple_back = SASS_MEMORY_COPY(simple_back);
   892                  auto name = simple_back->name();
   893                  name += simple_front->name();
   894                  simple_back->name(name);
   895                  tail->elements().back() = simple_back;
   896                  tail->elements().insert(tail->end(),
   897                    begin() + 1, end());
   898                }
   899                else {
   900                  tail->concat(this);
   901                }
   902              }
   903              else {
   904                tail->concat(this);
   905              }
   906
   907              complex->elements().back() = tail;
   908              // Append to results
   909              rv.push_back(complex);
   910            }
   911            else {
   912              // Can't insert parent that ends with a combinator
   913              // where the parent selector is followed by something
   914              if (parent && length() > 0) {
   915                throw Exception::InvalidParent(parent, traces, this);
   916              }
   917              // Create a copy to alter it
   918              complex = SASS_MEMORY_COPY(complex);
   919              // Just append ourself
   920              complex->append(this);
   921              // Append to results
   922              rv.push_back(complex);
   923            }
   924          }
   925        }
   926      }
   927
   928      // No parents
   929      else {
   930        // Create a new wrapper to wrap ourself
   931        auto complex = SASS_MEMORY_NEW(ComplexSelector, pstate());
   932        // Just append ourself
   933        complex->append(this);
   934        // Append to results
   935        rv.push_back(complex);
   936      }
   937
   938      return rv;
   939
   940    }

